const express = require('express');
const { Pool } = require('pg');
const { requireStaffAuth } = require('../middleware/staff');

const app = express();
const pool = new Pool({ connectionString: process.env.DATABASE_URL });

app.get('/api/admin/sessions/:sessionId/inspect', requireStaffAuth, async (req, res) => {
  const { sessionId } = req.params;

  // Retrieve the session from the PostgreSQL store
  const result = await pool.query(
    'SELECT sid, sess, expire FROM "session" WHERE sid = $1',
    [sessionId]
  );

  if (result.rows.length === 0) {
    return res.status(404).json({ error: 'Session not found or expired' });
  }

  const sessionData = result.rows[0].sess;
  const targetTenantId = sessionData?.passport?.user?.tenantId || sessionData?.tenantId;

  // Verify that staff member has active temporary support grant for the tenant
  const delegation = await pool.query(
    'SELECT id FROM support_delegations WHERE tenant_id = $1 AND staff_id = $2 AND expires_at > NOW() AND status = $3',
    [targetTenantId, req.staffUser.id, 'APPROVED']
  );

  if (delegation.rows.length === 0 && !req.staffUser.isSuperAdmin) {
    return res.status(403).json({
      error: 'Access denied: no active approved support delegation for the target tenant session'
    });
  }

  // Redact sensitive secrets before returning session dump
  const sanitizedSession = { ...sessionData };
  delete sanitizedSession.csrfSecret;
  delete sanitizedSession.oauthTokens;

  res.json({
    sessionId: result.rows[0].sid,
    sessionData: sanitizedSession,
    expiresAt: result.rows[0].expire
  });
});

app.listen(8096);
